export const WRAPPED_NATIVE_CURRENCY: Record<UniverseChainId, Token> = {
  [UniverseChainId.Mainnet]: WETH_ABSTRACT_MAINNET,
  [UniverseChainId.Sepolia]: WETH_ABSTRACT_TESTNET,
}

// Helper function to get tokens
export function getToken(chainId: UniverseChainId): {
  usdc: Token
  usdt?: Token
  dai?: Token
  weth: Token
  abx: Token
} {
  switch (chainId) {
    case UniverseChainId.Mainnet:
      return {
        usdc: USDC_ABSTRACT_MAINNET,
        usdt: USDT_ABSTRACT_MAINNET,
        dai: DAI_ABSTRACT_MAINNET,
        weth: WETH_ABSTRACT_MAINNET,
        abx: ABX_ABSTRACT_MAINNET,
      }
    case UniverseChainId.Sepolia:
      return {
        usdc: USDC_ABSTRACT_TESTNET,
        usdt: USDT_ABSTRACT_TESTNET,
        dai: DAI_ABSTRACT_TESTNET,
        weth: WETH_ABSTRACT_TESTNET,
        abx: ABX_ABSTRACT_TESTNET,
      }
    default:
      throw new Error(`Unsupported chain ID: ${chainId}`)
  }
}

